solution.Hex.java:
public class Hex {
    public static String dump(byte[] data) {
        StringBuilder out = new StringBuilder();
        for (int start = 0; start < data.length; start += 8) {
            if (start > 0) out.append('\n');
            out.append(String.format("%08x  ", start));
            StringBuilder hex = new StringBuilder();
            StringBuilder text = new StringBuilder();
            for (int i = start; i < Math.min(start + 8, data.length); i++) {
                int b = data[i] & 0xFF;
                hex.append(String.format("%02x ", b));
                text.append(b >= 32 && b <= 126 ? (char) b : '.');
            }
            out.append(String.format("%-24s", hex)).append(' ').append(text);
        }
        return out.toString();
    }
}

unitTests:
test("two lines", () -> {
    byte[] data = "Hello, Java!\n".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
    checkEq(Hex.dump(data), "00000000  48 65 6c 6c 6f 2c 20 4a  Hello, J\n00000008  61 76 61 21 0a           ava!.");
});

test("bytes above 127 and empty input", () -> {
    checkEq(Hex.dump(new byte[] { (byte) 0xff, 0, 65 }), "00000000  ff 00 41                 ..A");
    checkEq(Hex.dump(new byte[0]), "");
});

